/// Domain separation, so a token can never be confused with another HMAC value
/// derived under the same identity (an invite code, an approval token).
const LABEL_TOKEN: &[u8] = b"mcp/access-token/v1";

/// The read scope: listing and reading.
pub const SCOPE_READ: &str = "mcp:read";
/// Invoking a tool at all.
pub const SCOPE_TOOLS: &str = "mcp:tools";
/// Invoking a tool that mutates.
pub const SCOPE_WRITE: &str = "mcp:write";

/// The scopes an operation requires.
///
/// Computed per operation, not per connection: `tools/call` for a tool that
/// writes is not the same authority as `tools/list`. `writes` comes from the
/// server's own tool registry — a caller cannot declare its own tool harmless.
///
/// `server/discover` requires nothing. Discovery describes the server, and a
/// client must be able to learn how to authenticate before it can.
pub fn required_scopes(method: &str, writes: bool) -> Vec<&'static str> {
    match method {
        proto::M_DISCOVER => Vec::new(),
        proto::M_TOOLS_CALL | "tasks/get" => {
            if writes {
                vec![SCOPE_TOOLS, SCOPE_WRITE]
            } else {
                vec![SCOPE_TOOLS]
            }
        }
        "tasks/update" | "tasks/cancel" => vec![SCOPE_TOOLS, SCOPE_WRITE],
        "events/subscribe" | "events/unsubscribe" => vec![SCOPE_WRITE],
        "events/list" | "events/poll" | "events/stream" => vec![SCOPE_READ],
        // An unknown method is not a licence. It will be refused as
        // method-not-found, but it does not get a lower bar on the way there.
        _ => vec![SCOPE_READ],
    }
}

/// Does `granted` satisfy `required`, allowing for hierarchy?
///
/// `mcp:write` implies `mcp:read` and `mcp:tools`: a caller permitted to mutate
/// is necessarily permitted to look. Servers MUST account for hierarchies when
/// deciding sufficiency, and without this a write-scoped client would be refused
/// a listing it plainly may perform.
pub fn scopes_satisfy(granted: &[String], required: &[&str]) -> bool {
    required.iter().all(|need| {
        granted.iter().any(|have| {
            have == need || (have == SCOPE_WRITE && (*need == SCOPE_READ || *need == SCOPE_TOOLS))
        })
    })
}

